//! Port module: the weather / time-of-day / lighting frame loop (doc 52). Hand-written Rust for
//! `weather_update`, `weather_tod_segments_select` and the family of bilinear weather-record
//! blenders that call it, plus the weather / lighting callees of the frame loop.
//!
//! Every x87 sequence was read at the disassembly (the symbolic simulator in the scratchpad
//! decodes each `fnstsw ah` test), and the Rust bodies were run against the original machine code
//! natively (see the `tests` module): the x87 runs at 53-bit precision, so every operation that
//! stays on the x87 stack is an f64 operation here and every `fstp dword` is an `as f32`.
//!
//! The weather records are 0x1B8 bytes; the time-of-day select (0x4DDA50) picks two key frames
//! out of the table at 0x2526DD8 and fills a 0x20-byte out structure:
//! +0/+4 time-of-day nodes (0xD8 each), +8/+0xC the two weather records of the first key frame
//! (P, Q), +0x10/+0x14 the two of the second key frame, +0x18 the blend factor between the key
//! frames, +0x1C the one between P and Q. Each blender does X = lerp(c0, c1, t2),
//! Y = lerp(c2, c3, t2), out = lerp(X, Y, t) per field group, taking a record's value only when
//! its override bit (flag bytes at +0x1AC..+0x1B4) is set and the default record's otherwise.
//!
//! Threads: `weather_update`, `weather_rain_effects_update` and the callees ported from the
//! frame loop run on the game thread; 0x4D7E20 (and so the 0x4DF0C0 blender it calls) runs on
//! the render thread. Nothing here keeps state of its own besides atomics.

#![allow(unused_imports)]

use std::sync::atomic::{AtomicU32, AtomicUsize, Ordering};

use crate::portlib::*;
use crate::{detour, log};

const SHADOW_CALLS: u32 = 3000;

// --- globals -------------------------------------------------------------------------------------

const GAME_NOW: usize = 0x00E8_43AC;
const DT: usize = 0x00E8_437C; // frame time in seconds (f32)
const KEY_COUNT: usize = 0x0252_6DD4;
const KEY_TABLE: usize = 0x0252_6DD8; // 16-byte key frames
const NODE_BASE: usize = 0x0252_6DD0; // 0xD8-byte time-of-day nodes
const SEG_INDEX: usize = 0x0252_6DE8;
const SEG_COUNT: usize = 0x0252_6DE4;
const SEG_BASE: usize = 0x0252_6DEC; // 0x28-byte segments

const TWO_POW_32_F: f64 = 4294967296.0;
const TWO_POW_M32: f64 = f64::from_bits(0x3DF0_0000_0000_0000);
const HALF: f64 = 0.5;

/// A `fld dword` / `fstp dword` round trip of a 32-bit pattern: the bits, except that a
/// signalling NaN is quieted.
fn q32(bits: u32) -> u32 {
    if bits & 0x7F80_0000 == 0x7F80_0000 && bits & 0x007F_FFFF != 0 { bits | 0x0040_0000 } else { bits }
}

/// `call_regs` for a callee that returns on the x87 stack (popped as a qword).
unsafe fn call_regs_st0(f: usize, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, args: &[u32]) -> f64 {
    let mut out = 0f64;
    let block: [u32; 9] =
        [f as u32, ecx, edx, esi, edi, args.as_ptr() as u32, args.len() as u32, eax, &mut out as *mut f64 as u32];
    unsafe {
        std::arch::asm!(
            "push ebx", "push esi", "push edi", "push ebp",
            "mov ebp, esp",
            "mov ebx, eax",
            "mov ecx, [ebx + 24]",
            "mov esi, [ebx + 20]",
            "2:",
            "test ecx, ecx",
            "jz 3f",
            "push dword ptr [esi + ecx*4 - 4]",
            "dec ecx",
            "jmp 2b",
            "3:",
            "mov ecx, [ebx + 4]", "mov edx, [ebx + 8]", "mov esi, [ebx + 12]", "mov edi, [ebx + 16]",
            "mov eax, [ebx + 28]",
            "call dword ptr [ebx]",
            "mov ecx, [ebx + 32]",
            "fstp qword ptr [ecx]",
            "mov esp, ebp",
            "pop ebp", "pop edi", "pop esi", "pop ebx",
            inout("eax") block.as_ptr() => _, lateout("ecx") _, lateout("edx") _,
            clobber_abi("C"),
        );
    }
    out
}

// --- the port table and its shadow bookkeeping -------------------------------------------------

struct Port {
    name: &'static str,
    addr: usize,
    calls: AtomicU32,
    mismatches: AtomicU32,
    original: AtomicUsize,
}

const fn port(name: &'static str, addr: usize) -> Port {
    Port { name, addr, calls: AtomicU32::new(0), mismatches: AtomicU32::new(0), original: AtomicUsize::new(0) }
}

/// Count a call; `Some((call number, original copy))` while it should be shadowed.
fn shadowing(id: usize) -> Option<(u32, usize)> {
    let p = &PORTS[id];
    let n = p.calls.fetch_add(1, Ordering::Relaxed);
    let orig = p.original.load(Ordering::Relaxed);
    if n == SHADOW_CALLS && orig != 0 {
        log(&format!("port_weather: {}: {SHADOW_CALLS} calls shadowed, {} mismatched", p.name, p.mismatches.load(Ordering::Relaxed)));
    }
    (orig != 0 && n < SHADOW_CALLS).then_some((n, orig))
}

/// Count a call of a port without a shadow.
fn count(id: usize) {
    PORTS[id].calls.fetch_add(1, Ordering::Relaxed);
}

fn mismatch(id: usize, n: u32, what: String) {
    let m = PORTS[id].mismatches.fetch_add(1, Ordering::Relaxed) + 1;
    if m <= 10 {
        log(&format!("port_weather: {} mismatch (call {n}): {what}", PORTS[id].name));
    }
}

// --- 0x4DDA50 weather_tod_segments_select (cdecl out* -> AL) ---------------------------------------

/// The bit pattern of the 32-bit word at `a`.
unsafe fn ldf(a: usize) -> f64 {
    unsafe { f32::from_bits(rd(a)) as f64 }
}

/// Picks the two key frames around the time of day and fills the 0x20-byte `out` (see the module
/// doc). Returns EAX as the original leaves it: AL = 0 / 1; for the no-keys paths the upper bytes
/// are the key count's, on success they are those of `out[4]`.
///
/// With exactly one key frame the original returns 1 having written only `out+0x1C = 0.0`
/// (the rest of `out` stays as the caller had it).
pub(crate) unsafe fn tod_select(out: usize) -> u32 {
    unsafe {
        let n = rd(KEY_COUNT);
        if n == 0 || rd(SEG_COUNT) == 0 {
            return n & !0xFF;
        }
        if n == 1 {
            wf(out + 0x1C, 0.0);
            return 1;
        }
        // x: the random-looking time of day (a 32-bit unsigned scaled to [0, 1]), or the table
        // value while the replay flags select it.
        let r = rd(0x0140_E734);
        let mut xf = ((if (r as i32) < 0 { r as i32 as f64 + TWO_POW_32_F } else { r as i32 as f64 }) * TWO_POW_M32) as f32;
        if rb(0x0252_8B48) == 1 && rb(0x0252_8B49) == 0 && rb(0x0252_7B77) == 0 {
            xf = f32::from_bits(q32(rd(0x00E8_AF6C_usize.wrapping_add((rd(0x02A4_D138) as usize).wrapping_mul(4)))));
        }
        let x = xf as f64;
        let arr = rd(KEY_TABLE) as usize;
        // cur: the key frame at or before x; next: the one after it.
        let (cur, next): (usize, usize);
        let first_after = ldf(arr + 4) > x; // fcomp: key0.f4 > x, ordered
        if first_after {
            cur = (n as usize).wrapping_shl(4).wrapping_add(arr).wrapping_sub(0x10);
            next = arr;
        } else {
            let mut found = None;
            let last = n.wrapping_sub(1) as i32;
            let mut k = 0i32;
            if last > 0 {
                let mut e = arr + 0x10; // arr + 16 * (k + 1)
                loop {
                    let ek = e - 0x10;
                    // continue when entry k's time is above x or unordered
                    let k_gt = ldf(ek + 4) > x || ldf(ek + 4).is_nan() || x.is_nan();
                    if !k_gt {
                        // found when entry k+1's time is strictly above x
                        if ldf(e + 4) > x {
                            found = Some((ek, e));
                            break;
                        }
                    }
                    k += 1;
                    e += 0x10;
                    if k >= last {
                        break;
                    }
                }
            }
            match found {
                Some((ek, e)) => {
                    cur = ek;
                    next = e;
                }
                None => {
                    cur = (n as usize).wrapping_shl(4).wrapping_add(arr).wrapping_sub(0x10);
                    next = arr;
                }
            }
        }
        // d: distance from x to the next key's time, wrapped up by one when negative.
        let d = (ldf(next + 4) - x) as f32;
        let mut dd = d;
        if (d as f64) < 0.0 {
            dd = (d as f64 + 1.0) as f32;
        }
        let ddf = dd as f64;
        let f8 = ldf(cur + 8);
        let t2: f32 = if f8 < ddf { 0.0 } else { (1.0 - ddf / f8) as f32 };
        wf(out + 0x1C, t2);
        // The segment the time of day is in, and how far through it.
        let s = rd(SEG_INDEX);
        let seg = (rd(SEG_BASE) as usize).wrapping_add((s as usize).wrapping_mul(5).wrapping_mul(8));
        let r = call_regs(0x0068_B350, (seg + 0x10) as u32, s.wrapping_mul(5), 0, 0, 0, &[]) as i32;
        let nr = r.wrapping_neg();
        let v = rd(seg + 4) as i32;
        let u = ((nr as f64) / (v as f64)) as f32; // fidiv
        let h = v.wrapping_sub(v >> 31) >> 1;
        let base = rd(NODE_BASE);
        let div216 = |a: u32| -> u32 {
            let p = (a as i32 as i64) * 0x4BDA_12F7;
            let hi = (p >> 32) as i32 >> 6;
            (hi as u32).wrapping_add(hi as u32 >> 31)
        };
        let (r_val, i_first, i_second, lo): (f32, u32, u32, u32);
        let uf = u as f64;
        if nr > h && (s as i32) < (rd(SEG_COUNT) as i32).wrapping_add(-1) {
            // inside the segment: ramp up 0..0.5 over its second half
            let w = uf - HALF;
            let rv = if 0.0 < w {
                if w < HALF { w } else { HALF }
            } else {
                0.0
            };
            let f0 = rd(seg);
            let f0_next = rd(seg + 0x28);
            i_first = div216(f0.wrapping_sub(base));
            i_second = div216(f0_next.wrapping_sub(base));
            lo = (f0_next.wrapping_sub(base) as i32 as i64).wrapping_mul(0x4BDA_12F7) as u32;
            r_val = rv as f32;
        } else {
            let w = uf + HALF;
            let rv = if !(HALF < w) {
                HALF
            } else if w >= 1.0 {
                1.0
            } else {
                w
            };
            let f0 = rd(seg);
            let f0_prev = rd(seg.wrapping_sub(0x28));
            i_first = div216(f0_prev.wrapping_sub(base));
            i_second = div216(f0.wrapping_sub(base));
            lo = (f0.wrapping_sub(base) as i32 as i64).wrapping_mul(0x4BDA_12F7) as u32;
            r_val = rv as f32;
        }
        let t = call_regs_st0(0x00BF_0F50, lo, 0, 0, 0, 0, &[r_val.to_bits(), 1.0f32.to_bits(), 0.5f32.to_bits()]) as f32;
        wf(out + 0x18, t);
        let off1 = i_first.wrapping_mul(0x1B8);
        let off2 = i_second.wrapping_mul(0x1B8);
        wd(out, base.wrapping_add(i_first.wrapping_mul(0xD8)));
        wd(out + 4, base.wrapping_add(i_second.wrapping_mul(0xD8)));
        let p = rd(cur + 0xC);
        let q = rd(next + 0xC);
        wd(out + 8, p.wrapping_add(off1));
        wd(out + 0xC, off1.wrapping_add(q));
        let a4 = p.wrapping_add(off2);
        wd(out + 0x10, a4);
        wd(out + 0x14, off2.wrapping_add(q));
        (a4 & !0xFF) | 1
    }
}

// --- 0x4DE770 weather_update (cdecl, no args) ------------------------------------------------------

const WEATHER_EXPIRE_AT: usize = 0x00E9_D45C;
const WEATHER_FLAG: usize = 0x0252_6E18;
const SESSION: usize = 0x0252_8C14;

/// The 0x1B8-byte record fields, blended once per frame between the two records the transition
/// select (0x4DEED0) returns: `(b - a) * t + a`, f32 store per field (x87 53-bit in between).
/// Vector groups store the difference, the product and the sum separately (f32 each).
pub(crate) unsafe fn weather_update() {
    unsafe {
        if time_due(rd(WEATHER_EXPIRE_AT) as i32, rd(GAME_NOW) as i32) {
            wd(WEATHER_FLAG, 0);
        }
        call(0x004D_DD50);
        let s = rd(SESSION);
        if s != 0 && (rb(0x0252_8B56) == 0 || rb(0x0252_8B2B) != 0) && rb(s as usize + 0x3F8) != 0 {
            call(0x004D_E390);
        }
        let mut rec_a: u32 = 0;
        let mut rec_b: u32 = 0;
        let mut tt: f32 = 0.0;
        let pa = &mut rec_a as *mut u32 as u32;
        let pb = &mut rec_b as *mut u32 as u32;
        let pt = &mut tt as *mut f32 as u32;
        call_regs(0x004D_EED0, pt, pb, pa, 0, 0, &[pa, pb, pt]);
        let ra = std::ptr::read_volatile(&rec_a) as usize;
        let rbb = std::ptr::read_volatile(&rec_b) as usize;
        let t = std::ptr::read_volatile(&tt) as f64;
        // (b - a) * t + a, rounded once
        let lerp = |o: usize| -> f32 { ((ldf(rbb + o) - ldf(ra + o)) * t + ldf(ra + o)) as f32 };
        // the vector groups: each step stored as f32
        let vec3 = |o: usize, dst: usize| {
            let d0 = (ldf(rbb + o) - ldf(ra + o)) as f32;
            let d1 = (ldf(rbb + o + 4) - ldf(ra + o + 4)) as f32;
            let d2 = (ldf(rbb + o + 8) - ldf(ra + o + 8)) as f32;
            let m0 = (d0 as f64 * t) as f32;
            let m1 = (d1 as f64 * t) as f32;
            let m2 = (d2 as f64 * t) as f32;
            wf(dst, (ldf(ra + o) + m0 as f64) as f32);
            wf(dst + 4, (ldf(ra + o + 4) + m1 as f64) as f32);
            wf(dst + 8, (ldf(ra + o + 8) + m2 as f64) as f32);
        };
        wf(0x0252_6D74, lerp(0x18));
        let mut wind = lerp(0x3C);
        let wind2 = lerp(0x40);
        if rb(0x027A_6A40) & 8 != 0 {
            wind = (wind as f64 * 10.0) as f32;
        }
        wf(0x0252_6D54, wind);
        wf(0x0252_6D58, wind2);
        vec3(0x58, 0x0265_9828);
        vec3(0x64, 0x0265_9834);
        wf(0x00F9_E5D8, lerp(0x70));
        vec3(0x74, 0x0265_9840);
        wf(0x0252_6E08, lerp(0x44));
        vec3(0x48, 0x0265_984C);
        wf(0x0252_6E0C, lerp(0x54));
        wf(0x00F9_E5F0, lerp(0x90));
        wf(0x00F9_E5EC, lerp(0x94));
        wf(0x00F9_E5E8, lerp(0x98));
        wf(0x00F9_E5E4, lerp(0x9C));
        wf(0x00F9_E5E0, lerp(0xA0));
        wf(0x00F9_E5DC, lerp(0xA4));
        // the sky scroll: += lerp * dt, wrapped into [0, 1) by repeated subtraction
        let dt = ldf(DT);
        let l1 = lerp(0xA8) as f64;
        let mut s0 = (l1 * dt + ldf(0x0252_6E00)) as f32;
        wf(0x0252_6E00, s0);
        let l2 = lerp(0xAC) as f64;
        let mut s1 = (dt * l2 + ldf(0x0252_6E04)) as f32;
        wf(0x0252_6E04, s1);
        // while !(v < 1.0 || NaN): v = (v - 1.0) as f32
        while !((s0 as f64) < 1.0 || s0.is_nan()) {
            s0 = (s0 as f64 - 1.0) as f32;
            wf(0x0252_6E00, s0);
        }
        while !((s1 as f64) < 1.0 || s1.is_nan()) {
            s1 = (s1 as f64 - 1.0) as f32;
            wf(0x0252_6E04, s1);
        }
        wb(0x00F8_480E, 1);
        // fcompp: ST0 = a.rain, ST1 = b.rain; the byte stays 1 only when a.rain < b.rain
        if !(ldf(ra + 0x18) < ldf(rbb + 0x18)) {
            wb(0x00F8_480E, 0);
        }
    }
}

// --- 0x4CF840 weather_rain_effects_update (cdecl, no args) ---------------------------------------

const RAIN: usize = 0x0252_6D74;
const RAIN_EFFECT1: usize = 0x00F9_9900; // handle of the heavy-rain effect (rain >= 0.5)
const RAIN_EFFECT2: usize = 0x00F9_98FC; // handle of the light-rain effect (rain >= 0.1)
const HANDLE_TABLE: usize = 0x0214_9C64;

/// 0.1f widened, and 0.2f minus one ulp widened: the x87 constants of the scaling.
const C_0_1: f64 = f64::from_bits(0x3FB9_9999_A000_0000);
const C_0_2: f64 = f64::from_bits(0x3FC9_9999_8000_0000);

/// The live effect object of a handle when its kind (+0x4C) is 6, else 0.
unsafe fn effect_object(h: u32) -> u32 {
    unsafe {
        let o = rd(HANDLE_TABLE + (h as usize & 0xFFF) * 16);
        if o != 0 && rd(o as usize + 0x44) == h && rd(o as usize + 0x4C) == 6 { o } else { 0 }
    }
}

/// Build an effect parameter block with 0x4171C0 (ESI = the effect type) and start it with
/// 0x50E330; returns the handle.
unsafe fn start_effect(esi: u32) -> u32 {
    unsafe {
        let mut buf = [0u32; 0x40];
        let p = buf.as_mut_ptr() as usize;
        call_regs(0x0041_71C0, 0, 0x00EC_5AE4, 0x0252_A6D0, esi, 0, &[p as u32]);
        wb(p + 0x40, 0);
        wb(p + 0x34, 1);
        call_regs(0x0050_E330, 0, 0, 0, 0, 0, &[p as u32])
    }
}

/// `a x b` with each product rounded at 53 bits and the difference stored as f32.
fn cross(a: [f32; 3], b: [f32; 3]) -> [f32; 3] {
    let m = |x: f32, y: f32| x as f64 * y as f64;
    [(m(a[1], b[2]) - m(a[2], b[1])) as f32, (m(a[2], b[0]) - m(b[2], a[0])) as f32, (m(b[1], a[0]) - m(a[1], b[0])) as f32]
}

pub(crate) unsafe fn weather_rain_effects_update() {
    unsafe {
        if rb(0x0252_6D78) != 0 {
            wd(RAIN, q32(rd(0x0252_6D7C)));
        }
        let mut rain = ldf(RAIN);
        // fldz; fcomp rain: the rain is above zero (ordered)
        if 0.0 < rain {
            if rb(0x0252_6D79) == 0 {
                wd(0x0252_6D80, 3);
                for i in 0..3usize {
                    wd(0x0265_2FC4 + i * 0x310, rd(0x00E9_D318 + i * 8));
                    wd(0x0265_2FC4 + i * 0x310 + 4, rd(0x00E9_D318 + i * 8 + 4));
                }
            }
            wb(0x0252_6D79, 1);
            call(0x004C_E230);
        } else {
            wb(0x0252_6D79, 0);
            wd(0x0252_6D80, 0);
        }
        rain = ldf(RAIN);
        let mut want1 = false;
        let mut want2 = false;
        if 0.5 <= rain {
            if rd(RAIN_EFFECT1) == 0 {
                let h = start_effect(rd(0x00F9_9908));
                wd(RAIN_EFFECT1, h);
            }
            want1 = true;
        }
        let mut ebx = rd(RAIN_EFFECT2);
        if !(rain < C_0_1 || rain.is_nan()) {
            if ebx == 0 {
                ebx = start_effect(rd(0x00F9_9904));
                wd(RAIN_EFFECT2, ebx);
            }
            want2 = true;
        }
        if want1 || want2 {
            call(0x004C_F140);
            if want1 {
                let scale1 = ((ldf(RAIN) - 0.5) / C_0_2) as f32;
                let h = rd(RAIN_EFFECT1);
                let o = if h != 0 { effect_object(h) } else { 0 };
                if o != 0 {
                    call_regs(0x0050_AA60, 0, 0, 0x0265_41C0, o, 0, &[o, 0x025F_5B38]);
                    call_regs(0x0050_AD20, 0, rb(0x0252_6D7A) as u32, 0, o, 0, &[]);
                    call_regs(0x0050_AD90, 0, o, 0, 0, 0, &[scale1.to_bits()]);
                }
            }
            ebx = rd(RAIN_EFFECT2);
            if want2 && ebx != 0 {
                let o = effect_object(ebx);
                if o != 0 {
                    let mut p = [0f32; 3];
                    call_regs(0x00BD_DB40, 0, 0, 0, 0x0265_41D8, p.as_mut_ptr() as u32, &[]);
                    let v = [lf(0x00EC_5AD8), lf(0x00EC_5ADC), lf(0x00EC_5AE0)];
                    // e = normalize(p x v), c = normalize(e x p)
                    let mut e = cross(p, v);
                    call_regs(0x00BD_E150, 0, 0, 0, e.as_mut_ptr() as u32, 0, &[]);
                    let e = std::ptr::read_volatile(&e);
                    let mut c = cross(e, p);
                    call_regs(0x00BD_E150, 0, 0, 0, c.as_mut_ptr() as u32, 0, &[]);
                    let c = std::ptr::read_volatile(&c);
                    let mat: [f32; 9] = [e[0], e[1], e[2], p[0], p[1], p[2], c[0], c[1], c[2]];
                    call_regs(0x0050_AA60, 0, 0, 0x0265_41CC, 0, 0, &[o, mat.as_ptr() as u32]);
                    call_regs(0x0050_AD20, 0, rb(0x0252_6D7B) as u32, 0, o, 0, &[]);
                    let s = ((ldf(RAIN) - C_0_1) / C_0_1) as f32;
                    call_regs(0x0050_AD90, 0, o, 0, 0, 0, &[s.to_bits()]);
                }
            }
        }
        if !want1 {
            let h = rd(RAIN_EFFECT1);
            if h != 0 {
                call_regs(0x0050_DDB0, 0, 0, 0, h, 0, &[0, 1, 0]);
                ebx = rd(RAIN_EFFECT2);
                wd(RAIN_EFFECT1, 0);
            }
        }
        if !want2 && ebx != 0 {
            call_regs(0x0050_DDB0, 0, 0, 0, ebx, 0, &[0, 1, 0]);
            wd(RAIN_EFFECT2, 0);
        }
    }
}

// --- the weather-record blenders ----------------------------------------------------------------

/// One field group of a blender: for each of the four records `c0..c3` (out+8..out+0x14 of the
/// select) the value is at `rec + voff` when `rec[foff] & mask` is non-zero and at `default +
/// doff` otherwise; the four values are blended bilinearly into `out + out`.
#[derive(Clone, Copy)]
struct Blk {
    /// Three floats (each lerp step stored as f32) rather than one (the lerps stay on the x87).
    v3: bool,
    foff: usize,
    mask: u8,
    voff: usize,
    doff: usize,
    out: usize,
}

/// A float loaded and stored through the x87 (`fld dword` / `fstp dword`): the bits, quieted.
unsafe fn lf(a: usize) -> f32 {
    f32::from_bits(q32(unsafe { rd(a) }))
}

/// `(b - a) * t + a` on the x87 stack, rounded once to f32.
fn lerp1(a: f32, b: f32, t: f32) -> f32 {
    ((b as f64 - a as f64) * t as f64 + a as f64) as f32
}

/// The vector form: difference, product and sum each stored as f32.
fn lerp3_step(a: f32, b: f32, t: f32) -> f32 {
    let d = b - a;
    let m = d * t;
    a + m
}

unsafe fn run_blocks(blks: &[Blk], sel: &[u32; 8], d: usize, out: usize) {
    unsafe {
        let t = f32::from_bits(sel[6]);
        let t2 = f32::from_bits(sel[7]);
        for b in blks {
            let mut src = [0usize; 4];
            for k in 0..4 {
                let rec = sel[2 + k] as usize;
                src[k] = if rb(rec + b.foff) & b.mask != 0 { rec + b.voff } else { d + b.doff };
            }
            if b.v3 {
                let mut r = [0f32; 3];
                for j in 0..3 {
                    let p: [f32; 4] = [lf(src[0] + 4 * j), lf(src[1] + 4 * j), lf(src[2] + 4 * j), lf(src[3] + 4 * j)];
                    let x = lerp3_step(p[0], p[1], t2);
                    let y = lerp3_step(p[2], p[3], t2);
                    r[j] = lerp3_step(x, y, t);
                }
                for j in 0..3 {
                    wf(out + b.out + 4 * j, r[j]);
                }
            } else {
                let p: [f32; 4] = [lf(src[0]), lf(src[1]), lf(src[2]), lf(src[3])];
                let x = lerp1(p[0], p[1], t2);
                let y = lerp1(p[2], p[3], t2);
                wf(out + b.out, lerp1(x, y, t));
            }
        }
    }
}

/// The shared body: select, fall back to a copy of the default, else the blocks.
unsafe fn blend(blks: &[Blk], d: usize, out: usize, copy_n: usize) {
    unsafe {
        let mut sel = last_sel();
        if !select_ok(&mut sel) {
            copy_dwords(out, d, copy_n);
            return;
        }
        run_blocks(blks, &sel, d, out);
    }
}
