/// cdecl `(out*) -> AL`, shadowed on a snapshot of the 0x20-byte out structure.
extern "C" fn select_entry(out: usize) -> u32 {
    unsafe {
        let Some((n, orig)) = shadowing(SELECT) else { return tod_select(out) };
        let mut keep = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, keep.as_mut_ptr(), 8);
        let ra = call_regs(orig, 0, 0, 0, 0, 0, &[out as u32]);
        let mut theirs = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, theirs.as_mut_ptr(), 8);
        std::ptr::copy_nonoverlapping(keep.as_ptr(), out as *mut u32, 8);
        let rr = tod_select(out);
        let mut ours = [0u32; 8];
        std::ptr::copy_nonoverlapping(out as *const u32, ours.as_mut_ptr(), 8);
        if ours != theirs || rr != ra {
            mismatch(SELECT, n, format!("original {ra:#x} {theirs:x?}, Rust {rr:#x} {ours:x?}"));
            std::ptr::copy_nonoverlapping(theirs.as_ptr(), out as *mut u32, 8);
            return ra;
        }
        rr
    }
}

const RAIN_PORT: usize = 15;

extern "C" fn rain_effects_entry() {
    count(RAIN_PORT);
    unsafe { weather_rain_effects_update() }
}

extern "C" fn weather_update_entry() {
    count(UPDATE);
    unsafe { weather_update() }
}

/// Run a blender (`f` computes into the `regions` of `(address, length)` it writes): while shadowed
/// the original copy runs first on the real memory, the Rust result is compared with it and the
/// original's kept on a mismatch.
unsafe fn shadowed_blend(id: usize, p: &Pushad, arg0: u32, regions: &[(usize, usize)], f: impl Fn()) {
    unsafe {
        let Some((n, orig)) = shadowing(id) else {
            f();
            return;
        };
        let mut keep = [[0u8; 128]; 3];
        let mut theirs = [[0u8; 128]; 3];
        let mut ours = [[0u8; 128]; 3];
        let n_r = regions.len().min(3);
        let take = |dst: &mut [[u8; 128]; 3]| {
            for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
                std::ptr::copy_nonoverlapping(a as *const u8, dst[i].as_mut_ptr(), l.min(128));
            }
        };
        take(&mut keep);
        call_regs(orig, p.eax, p.ecx, p.edx, p.esi, p.edi, &[arg0]);
        take(&mut theirs);
        for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
            std::ptr::copy_nonoverlapping(keep[i].as_ptr(), a as *mut u8, l.min(128));
        }
        f();
        take(&mut ours);
        if ours != theirs {
            mismatch(id, n, format!("regions {regions:x?}: original and Rust outputs differ"));
            for (i, &(a, l)) in regions.iter().take(n_r).enumerate() {
                std::ptr::copy_nonoverlapping(theirs[i].as_ptr(), a as *mut u8, l.min(128));
            }
        }
    }
}

macro_rules! blender {
    ($entry:ident, $thunk:ident, $id:expr, $blks:ident, $copy:expr, $d:ident, $o:ident) => {
        extern "C" fn $entry(r: &mut Pushad, args: *const u32) {
            unsafe {
                let p = *r;
                let arg = *args;
                let d = p.$d as usize;
                let out = $o(&p, arg) as usize;
                shadowed_blend($id, &p, arg, &[(out, $copy * 4)], || blend(&$blks, d, out, $copy));
            }
        }
        regs_thunk!($thunk, $entry);
    };
}

fn out_ecx(p: &Pushad, _: u32) -> u32 {
    p.ecx
}
fn out_edi(p: &Pushad, _: u32) -> u32 {
    p.edi
}
fn out_arg(_: &Pushad, a: u32) -> u32 {
    a
}

